{"code": "from functools import cmp_to_key

def sort_versions(tags: list[str]) -> list[str]:
    """Sort git tags by Semantic Versioning precedence.

    Returns a new list sorted lowest precedence first. Preserves original
    tag strings (with leading 'v' if present). Tags differing only in build
    metadata maintain their input order.
    """

    def parse_version(tag: str) -> tuple:
        """Parse a version tag, return (major, minor, patch, pre-release-list, original)."""
        original = tag

        # Remove leading 'v' if present
        if tag.startswith('v'):
            tag = tag[1:]

        # Split off build metadata (ignored in precedence)
        if '+' in tag:
            tag = tag.split('+', 1)[0]

        # Split off pre-release
        if '-' in tag:
            version_part, prerelease = tag.split('-', 1)
        else:
            version_part = tag
            prerelease = None

        # Parse core version (MAJOR.MINOR.PATCH)
        parts = version_part.split('.')
        if len(parts) != 3:
            raise ValueError(original)

        try:
            major, minor, patch = [int(p) for p in parts]
        except ValueError:
            raise ValueError(original)

        # Validate no leading zeroes on core numbers
        for p in parts:
            if len(p) > 1 and p[0] == '0':
                raise ValueError(original)

        # Parse pre-release identifiers
        prerelease_parts = []
        if prerelease is not None:
            if not prerelease:
                raise ValueError(original)
            prerelease_parts = prerelease.split('.')

            # Check for empty identifiers
            if not all(prerelease_parts):
                raise ValueError(original)

            # Validate numeric pre-release identifiers (no leading zeroes)
            for part in prerelease_parts:
                if part.isdigit() and len(part) > 1 and part[0] == '0':
                    raise ValueError(original)

        return (major, minor, patch, prerelease_parts, original)

    def compare_prerelease(pre1: list[str], pre2: list[str]) -> int:
        """Compare pre-release identifier lists per SemVer 2.0.0 rules."""
        # Release versions have higher precedence than pre-release versions
        if not pre1 and not pre2:
            return 0
        if not pre1:
            return 1  # pre1 is release, has higher precedence
        if not pre2:
            return -1  # pre2 is release, has higher precedence

        # Compare identifiers from left to right
        for i in range(min(len(pre1), len(pre2))):
            id1, id2 = pre1[i], pre2[i]
            is_num1, is_num2 = id1.isdigit(), id2.isdigit()

            if is_num1 and is_num2:
                # Both numeric: compare as integers
                val1, val2 = int(id1), int(id2)
                if val1 < val2:
                    return -1
                if val1 > val2:
                    return 1
            elif is_num1:
                # Numeric < non-numeric
                return -1
            elif is_num2:
                # Non-numeric > numeric
                return 1
            else:
                # Both non-numeric: lexical comparison
                if id1 < id2:
                    return -1
                if id1 > id2:
                    return 1

        # If all preceding identifiers equal, longer list has higher precedence
        if len(pre1) < len(pre2):
            return -1
        if len(pre1) > len(pre2):
            return 1
        return 0

    # Parse all versions
    parsed = [parse_version(tag) for tag in tags]

    # Sort by SemVer precedence
    def compare(v1: tuple, v2: tuple) -> int:
        maj1, min1, pat1, pre1, _ = v1
        maj2, min2, pat2, pre2, _ = v2

        # Compare core version
        if maj1 != maj2:
            return -1 if maj1 < maj2 else 1
        if min1 != min2:
            return -1 if min1 < min2 else 1
        if pat1 != pat2:
            return -1 if pat1 < pat2 else 1

        # Build metadata ignored; compare pre-release
        return compare_prerelease(pre1, pre2)

    parsed.sort(key=cmp_to_key(compare))

    # Return original strings in sorted order
    return [p[-1] for p in parsed]
